package com.receiptledger.v1;
import android.app.Activity;import android.content.*;import android.graphics.Bitmap;import android.net.Uri;import android.os.Bundle;import android.provider.MediaStore;import android.view.Gravity;import android.widget.*;import com.receiptledger.v1.archive.*;import com.receiptledger.v1.document.*;import com.receiptledger.v1.image.*;import com.receiptledger.v1.item.*;import com.receiptledger.v1.ocr.*;import com.receiptledger.v1.persistence.*;import com.receiptledger.v1.recovery.*;import com.receiptledger.v1.review.ReceiptReviewDialog;import com.receiptledger.v1.ui.DocumentPreviewView;import com.receiptledger.v1.ui.SystemBarInsetHelper;import java.io.*;import java.util.*;import java.util.concurrent.*;
public final class MainActivity extends Activity {private static final int REQ_CAMERA=1001,REQ_PICK=1002;private final ExecutorService worker=Executors.newSingleThreadExecutor();private final ReceiptDocumentDetector detector=new ReceiptDocumentDetector();private final OcrRecoveryEngine ocrEngine=new OcrRecoveryEngine();private ReceiptRepository repository;private ReceiptRecord pendingRecord;private DocumentPreviewView preview;private TextView status,ocrText;private Button correctButton,originalButton,ocrButton,reviewButton,saveButton;private Uri pendingCaptureUri;private Bitmap sourceBitmap,correctedBitmap,displayBitmap;private Quad detectedQuad;private PerspectivePlan correctedPlan;private ProjectiveTransform displayToSource=ProjectiveTransform.identity();private long generation,displayRevision;
@Override protected void onCreate(Bundle b){super.onCreate(b);repository=new ReceiptRepository(getApplicationContext());int p=dp(12);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(p,p,p,p);root.setGravity(Gravity.CENTER_HORIZONTAL);TextView title=new TextView(this);title.setText(R.string.document_title);title.setTextSize(23);title.setGravity(Gravity.CENTER);LinearLayout a=new LinearLayout(this);a.setOrientation(LinearLayout.HORIZONTAL);a.setGravity(Gravity.CENTER);Button camera=button(R.string.capture,v->launchCamera()),gallery=button(R.string.gallery,v->launchPicker()),library=button(R.string.open_library,v->startActivity(new Intent(this,LibraryActivity.class)));correctButton=button(R.string.correct,v->correctPerspective());originalButton=button(R.string.original,v->showOriginal());ocrButton=button(R.string.run_ocr,v->runOcr());reviewButton=button(R.string.review_receipt,v->reviewCurrent());saveButton=button(R.string.save_receipt,v->saveCurrent());correctButton.setEnabled(false);originalButton.setEnabled(false);ocrButton.setEnabled(false);reviewButton.setEnabled(false);saveButton.setEnabled(false);a.addView(camera);a.addView(gallery);a.addView(correctButton);a.addView(originalButton);a.addView(ocrButton);a.addView(reviewButton);a.addView(saveButton);a.addView(library);preview=new DocumentPreviewView(this);status=new TextView(this);status.setText(R.string.recovery_body);status.setTextSize(14);status.setPadding(0,p,0,0);ocrText=new TextView(this);ocrText.setTextSize(13);ocrText.setMaxLines(15);ocrText.setTextIsSelectable(true);ocrText.setPadding(0,dp(8),0,0);root.addView(title,new LinearLayout.LayoutParams(-1,-2));root.addView(a,new LinearLayout.LayoutParams(-1,-2));root.addView(preview,new LinearLayout.LayoutParams(-1,0,1f));root.addView(status,new LinearLayout.LayoutParams(-1,-2));root.addView(ocrText,new LinearLayout.LayoutParams(-1,-2));setContentView(root);SystemBarInsetHelper.apply(this,root);worker.execute(()->repository.reconcileOrphans());}private Button button(int s,android.view.View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setOnClickListener(l);return b;}private void invalidateRecord(){ocrEngine.cancelPending();pendingRecord=null;if(reviewButton!=null)reviewButton.setEnabled(false);if(saveButton!=null)saveButton.setEnabled(false);}
private void launchCamera(){try{File d=new File(getCacheDir(),"captures");if(!d.exists()&&!d.mkdirs())throw new IOException("Cannot create capture directory");File f=File.createTempFile("receipt_",".jpg",d);pendingCaptureUri=new Uri.Builder().scheme("content").authority(getPackageName()+".capture").appendPath(f.getName()).build();Intent i=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);i.putExtra(MediaStore.EXTRA_OUTPUT,pendingCaptureUri);i.addFlags(Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri("ReceiptLedger capture",pendingCaptureUri));if(i.resolveActivity(getPackageManager())==null){Toast.makeText(this,R.string.no_camera,Toast.LENGTH_SHORT).show();return;}startActivityForResult(i,REQ_CAMERA);}catch(IOException e){Toast.makeText(this,getString(R.string.load_failed,e.getMessage()),Toast.LENGTH_LONG).show();}}
private void launchPicker(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,REQ_PICK);}@Override protected void onActivityResult(int rc,int r,Intent data){super.onActivityResult(rc,r,data);if(r!=RESULT_OK)return;Uri u=null;if(rc==REQ_CAMERA)u=pendingCaptureUri;else if(rc==REQ_PICK&&data!=null){u=data.getData();if(u!=null)try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException ignored){}}if(u!=null)loadImage(u);}
private void loadImage(Uri u){long t=++generation;displayRevision++;invalidateRecord();status.setText(R.string.loading);ocrText.setText("");correctButton.setEnabled(false);originalButton.setEnabled(false);ocrButton.setEnabled(false);worker.execute(()->{try{ImageLoader.LoadedImage l=ImageLoader.load(this,u);BitmapLumaAdapter.Sampled s=BitmapLumaAdapter.sample(l.bitmap,480);DocumentDetection d=detector.detect(s.plane);Quad q=d.found?s.toSource(d.quad):null;runOnUiThread(()->{if(t!=generation){l.bitmap.recycle();return;}if(sourceBitmap!=null&&sourceBitmap!=l.bitmap)sourceBitmap.recycle();if(correctedBitmap!=null){correctedBitmap.recycle();correctedBitmap=null;}sourceBitmap=l.bitmap;correctedPlan=null;detectedQuad=q;displayBitmap=sourceBitmap;displayToSource=ProjectiveTransform.identity();displayRevision++;preview.setDocument(sourceBitmap,detectedQuad);correctButton.setEnabled(q!=null);originalButton.setEnabled(false);ocrButton.setEnabled(true);status.setText(d.found?getString(R.string.detected,d.confidence,l.bitmap.getWidth(),l.bitmap.getHeight(),l.exifOrientation):getString(R.string.not_detected,d.reason,l.bitmap.getWidth(),l.bitmap.getHeight()));});}catch(Exception e){runOnUiThread(()->{if(t==generation)status.setText(getString(R.string.load_failed,e.getMessage()));});}});}
private void correctPerspective(){final Bitmap b=sourceBitmap;final Quad q=detectedQuad;if(b==null||q==null)return;long t=generation;invalidateRecord();status.setText(R.string.correcting);correctButton.setEnabled(false);worker.execute(()->{try{PerspectiveWarp.Result r=PerspectiveWarp.warp(b,q);runOnUiThread(()->{if(t!=generation){r.bitmap.recycle();return;}if(correctedBitmap!=null)correctedBitmap.recycle();correctedBitmap=r.bitmap;correctedPlan=r.plan;displayBitmap=correctedBitmap;displayToSource=correctedPlan.outputToSource;displayRevision++;preview.setDocument(correctedBitmap,null);ocrText.setText("");originalButton.setEnabled(true);correctButton.setEnabled(true);ocrButton.setEnabled(true);status.setText(getString(R.string.corrected,r.plan.outputWidth,r.plan.outputHeight));});}catch(Exception e){runOnUiThread(()->{if(t==generation){correctButton.setEnabled(true);status.setText(getString(R.string.correction_failed,e.getMessage()));}});}});}private void showOriginal(){if(sourceBitmap==null)return;invalidateRecord();displayBitmap=sourceBitmap;displayToSource=ProjectiveTransform.identity();displayRevision++;preview.setDocument(sourceBitmap,detectedQuad);ocrText.setText("");status.setText(R.string.showing_original);ocrButton.setEnabled(true);}
private void runOcr(){final Bitmap input=displayBitmap;if(input==null)return;final ProjectiveTransform mapper=displayToSource;final long it=generation,vt=displayRevision;invalidateRecord();ocrButton.setEnabled(false);status.setText(R.string.ocr_recovery_running);preview.setOcrQuads(null);ocrEngine.recognize(input,mapper,new OcrRecoveryEngine.Callback(){public void onSuccess(RecoveryResult result){if(it!=generation||vt!=displayRevision)return;ocrButton.setEnabled(true);RecognitionCandidate c=result.best;preview.setOcrQuads(displayQuads(c.document));int sw=sourceBitmap==null?input.getWidth():sourceBitmap.getWidth(),sh=sourceBitmap==null?input.getHeight():sourceBitmap.getHeight();boolean corrected=correctedBitmap!=null&&displayBitmap==correctedBitmap;pendingRecord=ReceiptRecordFactory.create(UUID.randomUUID().toString(),System.currentTimeMillis(),c.document,c.structure,c.items,c.validation,sw,sh,corrected);reviewButton.setEnabled(true);saveButton.setEnabled(false);renderRecord(pendingRecord,result);status.setText(getString(R.string.ocr_recovery_done,c.pass.name(),c.score,result.attemptedPasses(),c.validation.status.name()));}public void onFailure(Exception e){if(it!=generation||vt!=displayRevision)return;ocrButton.setEnabled(true);status.setText(getString(R.string.ocr_failed,e.getMessage()));}});}
private List<Quad> displayQuads(OcrDocument doc){List<Quad> out=new ArrayList<>();for(Quad q:doc.sourceElementQuads()){if(displayBitmap==correctedBitmap&&correctedPlan!=null)out.add(OcrGeometryMapper.map(q,correctedPlan.sourceToOutput));else out.add(q);}return out;}
private void reviewCurrent(){final ReceiptRecord base=pendingRecord;if(base==null)return;ReceiptReviewDialog.show(this,base,reviewed->{pendingRecord=reviewed;saveButton.setEnabled(true);renderRecord(reviewed,null);status.setText(getString(R.string.review_applied,reviewed.validationStatus.name(),reviewed.difference==null?"?":reviewed.difference.toString()));});}
private void renderRecord(ReceiptRecord r,RecoveryResult recovery){StringBuilder s=new StringBuilder();if(recovery!=null){s.append("[OCR passes]\n");for(PassDiagnostic d:recovery.diagnostics)s.append("• ").append(d).append('\n');s.append('\n');}s.append("[검증] ").append(r.validationStatus).append(" itemSum=").append(r.itemLineSum).append(" discount=").append(r.discountSum).append(" net=").append(r.computedNet).append(" total=").append(r.printedTotal).append(" diff=").append(r.difference).append("\nissues=").append(r.issues).append("\n\n[상품 후보]\n");for(PersistedItem item:r.items)s.append('[').append(item.resolution).append("] ").append(item.name).append(" | q=").append(item.quantity).append(" | unit=").append(item.unitPrice).append(" | amount=").append(item.lineAmount).append(" | origins=").append(item.quantityOrigin).append('/').append(item.unitPriceOrigin).append('/').append(item.lineAmountOrigin).append('\n');ocrText.setText(s.toString());}
private void saveCurrent(){final ReceiptRecord r=pendingRecord;final Bitmap image=sourceBitmap;if(r==null||image==null||!saveButton.isEnabled())return;saveButton.setEnabled(false);reviewButton.setEnabled(false);status.setText(R.string.saving_receipt);worker.execute(()->{try{ReceiptImageArchive.ArchiveEntry entry=repository.save(r,image);int count=repository.count();runOnUiThread(()->{if(pendingRecord==r){pendingRecord=null;status.setText(getString(R.string.saved_receipt,count,entry.bytes,entry.sha256.substring(0,12)));}});}catch(Exception e){runOnUiThread(()->{if(pendingRecord==r){reviewButton.setEnabled(true);saveButton.setEnabled(true);status.setText(getString(R.string.save_failed,e.getMessage()));}});}});}
@Override protected void onDestroy(){generation++;displayRevision++;worker.shutdownNow();ocrEngine.close();if(repository!=null)repository.close();super.onDestroy();}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}}
